/**
 * NearPay brand — "A. Convergence" (owner-approved 2026-11-11). React-free:
 *
 *   import { markSvg, logoSvg } from "@nearpay-internal/ui/brand";
 *   <Fragment set:html={logoSvg({ variant: "light", height: 32 })} />
 *
 * Several routes converge into one settlement dot. The geometry below is exact (viewBox 0 0 48 48)
 * and is the single source for the React components (`NearPayMark`, `NearPayLogo`), the static files
 * in `packages/ui/brand/` (generated by `scripts/build-brand.ts`) and the `nearpay-mark` icon.
 * Output uses presentation attributes only — no `style=""` (checkout CSP).
 */
import { WORDMARK, type WordmarkGlyph } from "./brand-wordmark.js";

export { WORDMARK, type WordmarkGlyph } from "./brand-wordmark.js";

const round = (n: number) => Math.round(n * 10000) / 10000;

/** The three routes (stroked, round caps). */
export const MARK_ROUTES_PATH = "M6 11c13 0 15 13 28 13M6 24h28M6 37c13 0 15-13 28-13";
/** The settlement dot. */
export const MARK_DOT = { cx: 40.5, cy: 24, r: 4.5 } as const;
export const MARK_VIEWBOX = "0 0 48 48";
/** Route stroke widths: regular, app icon (heavier on the tile), favicon (≤ 32 px). */
export const MARK_STROKE = { regular: 4.5, appIcon: 5, favicon: 6 } as const;
/** Dot radius at favicon sizes. */
export const MARK_FAVICON_DOT_R = 6;

/**
 * - `light`: on white / light surfaces — teal routes, violet dot.
 * - `dark`: on navy / dark surfaces — mint routes, light-violet dot (alias `onNavy`).
 * - `mono`: one colour, `currentColor` (single-colour print, embossing, inherited text colour).
 * - `app-icon`: teal rounded square (radius 25 %), white routes, mint dot.
 */
export type MarkVariant = "light" | "dark" | "onNavy" | "mono" | "app-icon";

export const BRAND_COLORS = {
  light: { routes: "#007A68", dot: "#5B5BD6" },
  dark: { routes: "#8EF0D3", dot: "#B4B4FF" },
  appIcon: { tile: "#007A68", routes: "#FFFFFF", dot: "#8EF0D3" },
  navy: "#12263F",
  wordmarkOnLight: "#12263F",
  wordmarkOnDark: "#FFFFFF",
} as const;

export interface MarkPaint {
  routes: string;
  dot: string;
  /** Tile fill (app icon only). */
  tile?: string;
  strokeWidth: number;
  dotR: number;
}

/** Colours and weights for a variant; `favicon` switches to the ≤ 32 px weights. */
export function markPaint(variant: MarkVariant, favicon = false): MarkPaint {
  const strokeWidth = favicon
    ? MARK_STROKE.favicon
    : variant === "app-icon"
      ? MARK_STROKE.appIcon
      : MARK_STROKE.regular;
  const dotR = favicon ? MARK_FAVICON_DOT_R : MARK_DOT.r;
  switch (variant) {
    case "dark":
    case "onNavy":
      return { ...BRAND_COLORS.dark, strokeWidth, dotR };
    case "mono":
      return { routes: "currentColor", dot: "currentColor", strokeWidth, dotR };
    case "app-icon":
      return {
        routes: BRAND_COLORS.appIcon.routes,
        dot: BRAND_COLORS.appIcon.dot,
        tile: BRAND_COLORS.appIcon.tile,
        strokeWidth,
        dotR,
      };
    default:
      return { ...BRAND_COLORS.light, strokeWidth, dotR };
  }
}

/** The mark's drawing (routes + dot) as SVG elements in the 48-unit box, without the `<svg>` wrapper. */
export function markBody(paint: Pick<MarkPaint, "routes" | "dot" | "strokeWidth" | "dotR">): string {
  return (
    `<path d="${MARK_ROUTES_PATH}" fill="none" stroke="${paint.routes}" stroke-width="${paint.strokeWidth}" stroke-linecap="round"/>` +
    `<circle cx="${MARK_DOT.cx}" cy="${MARK_DOT.cy}" r="${paint.dotR}" fill="${paint.dot}"/>`
  );
}

export interface AppIconOptions {
  /**
   * `rounded` — tile with radius 25 % and transparent corners (PWA "any", in-app use).
   * `square` — full-bleed tile (iOS apple-touch-icon: the OS rounds the corners).
   * `maskable` — full-bleed tile with the mark inside the 80 % safe circle (PWA "maskable").
   */
  shape?: "rounded" | "square" | "maskable";
  /** ≤ 32 px weights (stroke 6, dot r 6) and a larger mark, for tab icons. */
  favicon?: boolean;
}

/** App icon in the 48-unit box: teal tile, white routes, mint dot; the mark at 62.5 % (approved artboard). */
export function appIconBody(o: AppIconOptions = {}): string {
  const shape = o.shape ?? "rounded";
  const p = markPaint("app-icon", o.favicon);
  const scale = shape === "maskable" ? 0.5 : o.favicon ? 0.72 : 0.625;
  const offset = round((48 - 48 * scale) / 2);
  const tile =
    shape === "rounded"
      ? `<rect width="48" height="48" rx="12" fill="${p.tile}"/>`
      : `<rect width="48" height="48" fill="${p.tile}"/>`;
  return `${tile}<g transform="translate(${offset} ${offset}) scale(${scale})">${markBody(p)}</g>`;
}

const ESC: Record<string, string> = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };
const esc = (s: string) => s.replace(/[&<>"']/g, (c) => ESC[c] as string);

export interface MarkSvgOptions {
  variant?: MarkVariant;
  /** Pixel size (width = height). Default 32. */
  size?: number;
  /** Accessible name ("NearPay"); without it the SVG is decorative (`aria-hidden`). */
  title?: string;
  className?: string;
  /** Use the ≤ 32 px weights (stroke 6, dot r 6). Default: on when `size` ≤ 20. */
  favicon?: boolean;
  /** Include `xmlns` (standalone files). Default true. */
  xmlns?: boolean;
}

function svgOpen(
  viewBox: string,
  width: number,
  height: number,
  o: { title?: string; className?: string; xmlns?: boolean },
) {
  const a11y = o.title ? ` role="img" aria-label="${esc(o.title)}"` : ` aria-hidden="true"`;
  const cls = o.className ? ` class="${esc(o.className)}"` : "";
  const ns = o.xmlns === false ? "" : ` xmlns="http://www.w3.org/2000/svg"`;
  const title = o.title ? `<title>${esc(o.title)}</title>` : "";
  return `<svg${ns} viewBox="${viewBox}" width="${width}" height="${height}"${cls}${a11y} focusable="false">${title}`;
}

/** The mark as an SVG string. */
export function markSvg(o: MarkSvgOptions = {}): string {
  const variant = o.variant ?? "light";
  const size = o.size ?? 32;
  const favicon = o.favicon ?? size <= 20;
  const body = variant === "app-icon" ? appIconBody() : markBody(markPaint(variant, favicon));
  return `${svgOpen(MARK_VIEWBOX, size, size, o)}${body}</svg>`;
}

/**
 * Favicon (SVG): the ≤ 32 px mark that follows the browser's colour scheme — light colours by
 * default, mint/violet under `prefers-color-scheme: dark`. The `<style>` lives inside the SVG file
 * (served as an image), so it is unaffected by a page's CSP.
 */
export function faviconSvg(): string {
  const l = BRAND_COLORS.light;
  const d = BRAND_COLORS.dark;
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${MARK_VIEWBOX}" width="32" height="32">` +
    `<style>.r{stroke:${l.routes}}.d{fill:${l.dot}}@media (prefers-color-scheme:dark){.r{stroke:${d.routes}}.d{fill:${d.dot}}}</style>` +
    `<path class="r" d="${MARK_ROUTES_PATH}" fill="none" stroke="${l.routes}" stroke-width="${MARK_STROKE.favicon}" stroke-linecap="round"/>` +
    `<circle class="d" cx="${MARK_DOT.cx}" cy="${MARK_DOT.cy}" r="${MARK_FAVICON_DOT_R}" fill="${l.dot}"/>` +
    `</svg>`
  );
}

/* ------------------------------------------------------------------------------------------ */
/* Wordmark                                                                                     */
/* ------------------------------------------------------------------------------------------ */

/**
 * Letter-spacing (em) for the wordmark at a given font size, interpolated between the approved
 * artboards: ≤ 21 px −0.02em, 30 px −0.03em, ≥ 64 px −0.035em.
 */
export function wordmarkTracking(fontSize: number): number {
  const lerp = (x0: number, y0: number, x1: number, y1: number) =>
    round(y0 + ((fontSize - x0) / (x1 - x0)) * (y1 - y0));
  if (fontSize <= 21) return -0.02;
  if (fontSize <= 30) return lerp(21, -0.02, 30, -0.03);
  if (fontSize < 64) return lerp(30, -0.03, 64, -0.035);
  return -0.035;
}

/** Width of the outlined wordmark, in em, at a given tracking (em). */
export function wordmarkWidth(tracking: number, glyphs: readonly WordmarkGlyph[] = WORDMARK.glyphs): number {
  let x = 0;
  glyphs.forEach((g, i) => {
    x += g.advance;
    if (i < glyphs.length - 1) x += tracking;
  });
  return x;
}

/**
 * The outlined "NearPay" wordmark (Instrument Sans 650) as SVG elements: baseline at y = 0, x from
 * 0, 1 em = 1 unit. Scale and translate it with a wrapping `<g>`.
 */
export function wordmarkBody(fill: string, tracking: number): string {
  let x = 0;
  const parts: string[] = [];
  WORDMARK.glyphs.forEach((g, i) => {
    parts.push(`<path transform="translate(${Math.round(x * 10000) / 10} 0)" d="${g.d}"/>`);
    x += g.advance + (i < WORDMARK.glyphs.length - 1 ? tracking : 0);
  });
  // Glyph data is in font units (1000 per em).
  return `<g fill="${fill}" transform="scale(0.001)">${parts.join("")}</g>`;
}

export interface LogoSvgOptions {
  /** `light` (navy wordmark), `dark` (white wordmark, on navy) or `mono` (currentColor). */
  variant?: "light" | "dark" | "onNavy" | "mono";
  /** Height in px of the mark (the tallest element). Default 40. */
  height?: number;
  title?: string;
  className?: string;
  xmlns?: boolean;
}

/** Proportions of the lock-up, relative to the wordmark font size (from the approved artboards). */
export const LOGO_PROPORTIONS = {
  /** Mark size ÷ wordmark font size (88 / 64). */
  mark: 1.375,
  /** Gap ÷ font size (18 / 64 ≈ 0.28, 12 / 30 = 0.4 — 0.32 reads well at every size). */
  gap: 0.32,
} as const;

/** The full lock-up (mark + outlined wordmark) as an SVG string; no font needed to display it. */
export function logoSvg(o: LogoSvgOptions = {}): string {
  const variant = o.variant ?? "light";
  const height = o.height ?? 40;
  const fontSize = height / LOGO_PROPORTIONS.mark;
  const tracking = wordmarkTracking(fontSize);
  // Work in a box where the mark is 48 units tall.
  const unit = 48 / LOGO_PROPORTIONS.mark; // font size in box units
  const gap = LOGO_PROPORTIONS.gap * unit;
  const wordX = 48 + gap;
  const width = wordX + wordmarkWidth(tracking) * unit;
  const baseline = 24 + (WORDMARK.capHeight * unit) / 2;
  const paint = markPaint(variant === "onNavy" ? "dark" : variant, false);
  const fill =
    variant === "mono"
      ? "currentColor"
      : variant === "light"
        ? BRAND_COLORS.wordmarkOnLight
        : BRAND_COLORS.wordmarkOnDark;
  const vbW = round(width);
  const pxW = round((width / 48) * height);
  return (
    `${svgOpen(`0 0 ${vbW} 48`, pxW, height, { ...o, title: o.title })}` +
    markBody(paint) +
    `<g transform="translate(${round(wordX)} ${round(baseline)}) scale(${round(unit)})">${wordmarkBody(fill, tracking)}</g>` +
    `</svg>`
  );
}
